            consume()
            val = parse_expr()
            t2, _ = peek()
            if t2 == ')':
                consume()
            else:
                raise ValueError("Expected ')'")
            return val
        else:
            raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    return result

